import json, subprocess
from pathlib import Path

repo=Path("/Users/steventran/do-again")

def run(args):
    return subprocess.run(args,cwd=repo,text=True,capture_output=True,check=False)

issue10 = run(["gh","issue","view","10","--json","body,comments"])
if issue10.returncode:
    print(issue10.stderr)
    raise SystemExit(issue10.returncode)
data=json.loads(issue10.stdout)
body=str(data.get("body") or "")
comments="\n".join(str(c.get("body") or "") for c in data.get("comments") or [])
text=body+"\n"+comments

criteria={
  "idle_after_receipt":["idle after receipt","no-progress","bounded continuation"],
  "queued_delivery":["queued delivery","browser outbox","pending_receipts"],
  "long_running_claim":["long-running claim","claimed request","waiting_for_execution"],
  "crash_auth_network":["crash","auth","network","TimeoutError","BrowserError"],
  "visible_incident":["incident","issue_report","stalled_ci_handoff","visible"],
  "no_duplicates":["duplicate","exactly once","no replay"],
  "three_projects":["jobpipe","Sonary","Do Again"],
}
evidence={}
low=text.lower()
for name,terms in criteria.items():
    evidence[name]={t:(t.lower() in low) for t in terms}

print(json.dumps({
  "issue_title_or_body_excerpt": body[:4000],
  "criteria_evidence": evidence,
  "comment_count": len(data.get("comments") or []),
},indent=2,sort_keys=True))

# Also summarize current test inventory around live/soak/recovery.
for path in sorted((repo/"tests").glob("test_*.py")):
    s=path.read_text(errors="ignore").lower()
    hits=[k for k in ["soak","claim","browser","liveness","incident","timeout","auth","network","outbox"] if k in s]
    if hits:
        print(path.name, ",".join(hits))
